{
  "schemaVersion": "0.2",
  "slug": "stack",
  "name": "Stack",
  "status": "experimental",
  "purpose": "One-dimensional layout primitive for spacing, alignment, and optional fill/grow.",
  "scenarios": [
    "Stack form fields vertically with consistent spacing",
    "Arrange toolbar actions horizontally",
    "Stretch children across a workspace pane or fill a flex parent with grow"
  ],
  "props": {
    "direction": {
      "type": "enum",
      "required": false,
      "description": "Main axis of the flex container.",
      "values": [
        "row",
        "column"
      ],
      "default": "column"
    },
    "gap": {
      "type": "enum",
      "required": false,
      "description": "Spacing step applied to the gap.",
      "values": [
        "0",
        "1",
        "2",
        "3",
        "4",
        "5",
        "6"
      ],
      "default": "2"
    },
    "align": {
      "type": "enum",
      "required": false,
      "description": "Cross-axis alignment of children. stretch fills the cross axis (full inline size in a column stack).",
      "values": [
        "start",
        "center",
        "end",
        "stretch"
      ],
      "default": "stretch"
    },
    "justify": {
      "type": "enum",
      "required": false,
      "description": "Main-axis distribution of children.",
      "values": [
        "start",
        "center",
        "end",
        "between"
      ],
      "default": "start"
    },
    "grow": {
      "type": "boolean",
      "required": false,
      "description": "Grow to fill a flex/grid parent (panes, shell columns, toolbars). Sets flex: 1 1 auto and self stretch.",
      "default": false
    }
  },
  "variants": [
    {
      "name": "direction",
      "values": [
        "row",
        "column"
      ],
      "default": "column",
      "description": "Main axis of the flex container."
    }
  ],
  "states": [
    {
      "name": "default",
      "description": "Flex container is rendered."
    }
  ],
  "composition": {
    "allowedParents": [
      "app-shell",
      "dialog",
      "form",
      "page",
      "workspace-split",
      "scroll-pane",
      "card"
    ],
    "allowedChildren": [
      "any"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use physical margins; use the gap prop.",
    "Do not nest deeply to avoid flexbox performance issues.",
    "Do not freeze Stack direction=row for multi-column workspaces that must morph on phone — use WorkspaceSplit."
  ],
  "a11y": {
    "role": "generic",
    "keyboard": [],
    "focus": "Stack is not focusable; it only affects layout.",
    "labeling": "Children provide their own labels.",
    "wcag": [
      "1.3.2"
    ]
  },
  "responsive": {
    "strategy": "Direction can switch at breakpoints via the direction prop; spacing is token-based.",
    "breakpoints": {
      "compact": "Stacks stay within the viewport width; gap is preserved.",
      "medium": "Direction may switch to row if space allows.",
      "large": "Direction may switch to row if space allows."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir; row follows the flow.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "stack",
    "states": [
      "row",
      "column"
    ],
    "intents": [
      "layout-flow"
    ]
  }
}

import type { ReactNode } from 'react'
import './styles.css'

export type StackDirection = 'row' | 'column'
export type StackGap = '0' | '1' | '2' | '3' | '4' | '5' | '6'
export type StackAlignment = 'start' | 'center' | 'end' | 'stretch'
export type StackJustify = 'start' | 'center' | 'end' | 'between'

export interface StackProps {
  direction?: StackDirection
  gap?: StackGap
  /** Cross-axis alignment. Default `stretch` fills the cross axis (full width in a column stack). */
  align?: StackAlignment
  /** Main-axis distribution. */
  justify?: StackJustify
  /**
   * Grow to fill a flex/grid parent (workspace panes, shell columns, toolbars).
   * Sets `flex: 1 1 auto` + self stretch; pair with `align="stretch"` for children.
   */
  grow?: boolean
  children: ReactNode
  className?: string
}

export function Stack({
  direction = 'column',
  gap = '2',
  align = 'stretch',
  justify = 'start',
  grow = false,
  children,
  className,
}: StackProps) {
  const classes = [
    'cu-stack',
    `cu-stack--${direction}`,
    `cu-stack--gap-${gap}`,
    `cu-stack--align-${align}`,
    `cu-stack--justify-${justify}`,
    grow ? 'cu-stack--grow' : '',
    className,
  ]
    .filter(Boolean)
    .join(' ')

  return (
    <div
      className={classes}
      data-ai-role="stack"
      data-ai-intent="layout-flow"
      data-ai-state="default"
      data-direction={direction}
      data-gap={gap}
      data-align={align}
      data-justify={justify}
      data-grow={grow ? 'true' : 'false'}
    >
      {children}
    </div>
  )
}

.cu-stack {
  display: flex;
  flex-direction: column;
  gap: var(--cu-space-2);
  align-items: stretch;
  justify-content: flex-start;
  /* Nested flex/grid panes must be allowed to shrink so stretch/grow can resolve. */
  min-block-size: 0;
  min-inline-size: 0;
}

.cu-stack--row {
  flex-direction: row;
}

.cu-stack--column {
  flex-direction: column;
}

.cu-stack--gap-0 {
  gap: 0;
}

.cu-stack--gap-1 {
  gap: var(--cu-space-1);
}

.cu-stack--gap-2 {
  gap: var(--cu-space-2);
}

.cu-stack--gap-3 {
  gap: var(--cu-space-3);
}

.cu-stack--gap-4 {
  gap: var(--cu-space-4, 1rem);
}

.cu-stack--gap-5 {
  gap: var(--cu-space-5, 1.5rem);
}

.cu-stack--gap-6 {
  gap: var(--cu-space-6, 2.5rem);
}

/*
 * Align / justify use class modifiers (same pattern as direction/gap).
 * data-align / data-justify alone are not enough: align="start" previously
 * had no CSS rule, so the base stretch value never switched off.
 */
.cu-stack--align-start {
  align-items: flex-start;
}

.cu-stack--align-center {
  align-items: center;
}

.cu-stack--align-end {
  align-items: flex-end;
}

.cu-stack--align-stretch {
  align-items: stretch;
}

.cu-stack--justify-start {
  justify-content: flex-start;
}

.cu-stack--justify-center {
  justify-content: center;
}

.cu-stack--justify-end {
  justify-content: flex-end;
}

.cu-stack--justify-between {
  justify-content: space-between;
}

/* Fill a flex/grid parent (toolbars, WorkspaceSplit panes, AppShell columns). */
.cu-stack--grow {
  flex: 1 1 auto;
  align-self: stretch;
  justify-self: stretch;
}

/*
 * Cross-axis stretch: keep flex children from overflowing the stack while still
 * letting align-items:stretch expand them (Buttons are inline-flex).
 */
.cu-stack--align-stretch.cu-stack--column > * {
  max-inline-size: 100%;
}

.cu-stack--align-stretch.cu-stack--row > * {
  max-block-size: 100%;
}
